import { memo, ReactElement } from 'react';
import { ToggleSwitchProps } from './toggle-switch';

export type ToggleSwitchSectionProps = {
  label: string;
  desc?: string;
  children: ReactElement<ToggleSwitchProps>;
};

export const ToggleSwitchSection = memo(function ToggleSwitchSection({
  label,
  desc,
  children,
}: ToggleSwitchSectionProps) {
  return (
    <div className="toggle-area">
      <div className="toggle-box">
        <p className="toggle-label">{label}</p>
        {children}
      </div>
      {desc && <p className="toggle-info whitespace-pre-wrap">{desc}</p>}
    </div>
  );
});
